        "why": "The Fandom Gender Dynamics chart needs character gender and all relationship types for the two fandoms; the file supplies only M/M ships and no gender variables."
    }
]

with open('skipped.json','w') as f:
    json.dump(skipped, f, indent=2, ensure_ascii=False)
print(len(skipped))
